34	        },
35	      ],
36	    });
37	
38	    expect(result).toEqual({ results: [{ premium: 71 }] });
39	  });
40	  it("plain staff (base 80 G) for a newcomer → premium 93 G (80 + 8 first insurance + 5 fee)", () => {
41	    const result = runScenario({
42	      customer: { yearsWithMHPCO: 0 },
43	      steps: [
44	        {
45	          op: "quote",
46	          items: [{ type: "staff", material: "oak", enchantment: 1, cursed: false }],
47	        },
48	      ],
49	    });
50	
51	    expect(result).toEqual({ results: [{ premium: 93 }] });
52	  });
53	  it("plain potion (base 40 G) for a newcomer → premium 49 G (40 + 4 first insurance + 5 fee)", () => {
54	    const result = runScenario({
55	      customer: { yearsWithMHPCO: 0 },
56	      steps: [
57	        {
58	          op: "quote",
59	          items: [{ type: "potion", material: "glass", enchantment: 0, cursed: false }],
60	        },
61	      ],
62	    });
63	
64	    expect(result).toEqual({ results: [{ premium: 49 }] });
65	  });
66	
67	  // --- Components and blocks of 3 alike -----------------------------------
68	  it("1 rune → 25 G base premium", () => {
69	    const result = runScenario({
70	      customer: { yearsWithMHPCO: 0 },
71	      steps: [{ op: "quote", items: [{ type: "rune" }] }],
72	    });
73	
74	    // 25 base + 2.5 first insurance + 5 fee = 32.5; rounding is not yet
75	    // implemented (see the rounding todos), so the raw value is asserted here.
76	    expect(result).toEqual({ results: [{ premium: 32.5 }] });
77	  });
78	  it.todo("2 runes → 50 G base premium");
79	  it.todo("3 runes → 60 G base premium (block applies)");
80	  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
81	  it.todo("7 runes → 175 G base premium");
82	  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
83	  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
