119	  // --- Claim: special clauses ----------------------------------------------
120	  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
121	  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement then deductible)");
122	  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
123	  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
124	
125	  // --- Claim: deductible per damage event ----------------------------------
126	  it.todo("dragon attack damages sword (500 G) and amulet (300 G) → payout 600 G (deductible once per damaged item)");
127	  it.todo("dragon attack damages both of two insured swords → each damage entry gets its own deductible");
128	  it.todo("damage amount below the deductible does not produce a negative payout");
129	
130	  // --- Claim: cap ----------------------------------------------------------
131	  it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
132	  it.todo("sword policy, second successive claim of 1500 G → payout 600 G, remainingCap 0 G (reduced to remaining cap)");
133	
